/* PropertyOS service worker */
// Cache name and precache lists are generated by build.mjs (hash of the release's file manifest).
const CACHE = '__CACHE_NAME__';

const PRECACHE = /*__PRECACHE__*/[];
/* Essential shell must succeed; other assets are best-effort. */
const ESSENTIAL = /*__ESSENTIAL__*/[];

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(CACHE);
    await Promise.all(ESSENTIAL.map((u) => c.add(u)));
    await Promise.allSettled(PRECACHE.filter((u) => !ESSENTIAL.includes(u)).map((u) => c.add(u)));
    self.skipWaiting();
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    Promise.all([
      caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith("propertyos-") && k !== CACHE).map((k) => caches.delete(k)))),
      self.registration.navigationPreload && self.registration.navigationPreload.disable(),
    ]).then(() => self.clients.claim())
  );
});

const isStatic = (u) => /\/(assets|vendor)\//.test(u.pathname);

self.addEventListener('fetch', (e) => {
  const r = e.request, u = new URL(r.url);
  if (r.method !== 'GET' || u.origin !== location.origin) return;

  // Cache only the built shell. Never persist arbitrary API or receipt responses.
  const shell = new Set(PRECACHE.map((p) => new URL(p, self.registration.scope).pathname));
  if (!shell.has(u.pathname)) return;

  const match = (request) => caches.open(CACHE).then((cache) => cache.match(request));
  const put = (res) => {
    if (res && res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(r, copy)); }
    return res;
  };

  if (isStatic(u)) {
    e.respondWith(match(r).then((m) => m || fetch(r).then(put)));
    return;
  }

  e.respondWith((async () => {
    const net = Promise.resolve(e.preloadResponse).then((res) => res || fetch(r));
    try {
      const res = await Promise.race([net, new Promise((_, rej) => setTimeout(rej, 2500))]);
      return put(res);
    } catch (_) {
      const hit = (await match(r)) || (r.mode === 'navigate' && (await match('index.html')));
      return hit || net.then(put).catch(() => Response.error());
    }
  })());
});
